#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
example_low_level_io_all.py

Demonstrates:
- Initializing DDS via ChannelFactory
- Subscribing (optionally) to:
    - B1LowStateSubscriber (joint + IMU state)
    - B1OdometerStateSubscriber (odometry)
    - B1LowHandDataScriber (hand joint state)
    - B1LowHandTouchDataScriber (tactile arrays)
- Publishing LowCmd periodically via B1LowCmdPublisher (optional):
    - Behavior: move joints 2–9 from
      [0.2, -1.45, 0.0, -0.5, 0.2, 1.45, 0.0, 0.5]
      to 0 with smooth interpolation over 3 seconds

Command-line options:
    --subs  Comma-separated: low_state,odom,hand_data,hand_touch,all,none
    --pubs  Comma-separated: lowcmd,all,none

Examples:
    Enable all (default):
        python example_low_level_io_all.py

    Enable only low_state and odom subscriptions; disable LowCmd publisher:
        python example_low_level_io_all.py --subs low_state,odom --pubs none

    Enable only LowCmd publisher (joints 2–9 interpolate to 0 in 3 seconds); no subscriptions:
        python example_low_level_io_all.py --subs none --pubs lowcmd
"""

import time
import math
import signal
import argparse

import booster_robotics_sdk_python as br


# ========== DDS initialization ==========

def init_dds(domain_id: int = 0, iface: str = ""):
    """
    Initialize DDS communication. Must be called once before using channels.
    """
    factory = br.ChannelFactory.Instance()
    factory.Init(domain_id, iface)


# ========== LowCmd construction and publishing ==========

def create_base_lowcmd() -> br.LowCmd:
    """
    Build a base LowCmd:
    - PARALLEL mode
    - All joints: q/dq/tau = 0
    - kp/kd set to conservative values
    """
    cmd = br.LowCmd()
    cmd.cmd_type = br.LowCmdType.PARALLEL

    # Prefer the joint count exposed by the SDK; fall back to 22 if absent
    joint_cnt = int(getattr(br, "kJointCnt", 28))

    motors = []
    for _ in range(joint_cnt):
        m = br.MotorCmd()
        m.mode = 0          # Actual mode depends on the firmware; example only
        m.q = 0.0
        m.dq = 0.01
        m.tau = 0.0
        m.kp = 30.0
        m.kd = 1.5
        m.weight = 1.0
        motors.append(m)

    cmd.motor_cmd = motors
    return cmd


# ========== Joints 0–9: smooth interpolation to 0 within 3 seconds ==========

START_ANGLES = [0.0, 0.0, 
                0.2, -1.0, 0.0, -0.8, 0.0,  0.0, 0.0,
                0.2, 1.0,  0.0, 0.5,  0.0,0.0,0.0]   # For joints 0–15
END_ANGLES = [0.0, 0.0, 
                0.2, -1.0, 0.0, -0.8, 0.0,  0.0, 0.0, 
                0.2, 1.0, 0.0, 0.8,  0.5,  0.5, 0.5]               # Final target is 0 for all
#START_ANGLES = [3.0, 3.0, 0.0]
#END_ANGLES = [0.0, 3.0, 0.0]
def generate_joints_down_trajectory(duration_sec: float = 3.0,
                                 dt: float = 0.02):

    if duration_sec <= 0.0:
        duration_sec = 3.0
    if dt <= 0.0:
        dt = 0.02

    num_frames = int(duration_sec / dt) + 1
    if num_frames < 2:
        num_frames = 2

    traj = []
    for i in range(num_frames):
        s = i / (num_frames - 1)
        smooth = 0.5 * (1.0 - math.cos(math.pi * s))  # 0 → 1
        frame = []
        for start, end in zip(START_ANGLES, END_ANGLES):
            angle = start * (1.0 - smooth) + end * smooth
            frame.append(angle)
        traj.append(frame)

    return traj

def apply_joint_trajectory(cmd: br.LowCmd, frame_idx: int, traj):
    """
    Write the specified trajectory frame into LowCmd (override q/kp/kd/mode for joints 2–9).

    Joint mapping:
    - Left arm: joints 2, 3, 4, 5
    - Right arm: joints 6, 7, 8, 9

    Returns the clamped frame index for debugging.
    """
    if not traj:
        return frame_idx

    num_frames = len(traj)
    if num_frames == 0:
        return frame_idx

    # Clamp to the last frame so that joints stay at the final posture
    if frame_idx >= num_frames:
        frame_idx = num_frames - 1
    if frame_idx < 0:
        frame_idx = 0

    frame = traj[frame_idx]  # length = 8

    motors = cmd.motor_cmd

    # Unified control parameters (adjust as needed)
    mode = 1    # Example: assume 1 = position mode
    kp = 30.0
    kd = 2.0

    # Global joint indices 2–9
    for local_idx in range(16):
        j = local_idx
        if j >= len(motors):
            # For robot models with fewer than 10 joints
            break
        m = motors[j]
        m.mode = mode
        m.kp = kp
        m.kd = kd
        m.q = float(frame[local_idx])

    cmd.motor_cmd = motors
    return frame_idx

def generate_arm_down_trajectory(duration_sec: float = 3.0,
                                 dt: float = 0.02):
    """
    Generate a smooth trajectory for joints 2–9 from START_ANGLES to END_ANGLES.

    Uses a cosine-based ease-in/ease-out:
        s ∈ [0,1]
        smooth = 0.5 * (1 - cos(pi * s))
        angle = start * (1 - smooth) + end * smooth
    """
    if duration_sec <= 0.0:
        duration_sec = 3.0
    if dt <= 0.0:
        dt = 0.02

    num_frames = int(duration_sec / dt) + 1
    if num_frames < 2:
        num_frames = 2

    traj = []
    for i in range(num_frames):
        s = i / (num_frames - 1)
        smooth = 0.5 * (1.0 - math.cos(math.pi * s))  # 0 → 1
        frame = []
        for start, end in zip(START_ANGLES, END_ANGLES):
            angle = start * (1.0 - smooth) + end * smooth
            frame.append(angle)
        traj.append(frame)

    return traj


def apply_arm_trajectory(cmd: br.LowCmd, frame_idx: int, traj):
    """
    Write the specified trajectory frame into LowCmd (override q/kp/kd/mode for joints 2–9).

    Joint mapping:
    - Left arm: joints 2, 3, 4, 5
    - Right arm: joints 6, 7, 8, 9

    Returns the clamped frame index for debugging.
    """
    if not traj:
        return frame_idx

    num_frames = len(traj)
    if num_frames == 0:
        return frame_idx

    # Clamp to the last frame so that joints stay at the final posture
    if frame_idx >= num_frames:
        frame_idx = num_frames - 1
    if frame_idx < 0:
        frame_idx = 0

    frame = traj[frame_idx]  # length = 8

    motors = cmd.motor_cmd

    # Unified control parameters (adjust as needed)
    mode = 1    # Example: assume 1 = position mode
    kp = 40.0
    kd = 3.0

    # Global joint indices 2–9
    for local_idx in range(1):
        j = 2 + local_idx
        if j >= len(motors):
            # For robot models with fewer than 10 joints
            break
        m = motors[j]
        m.mode = mode
        m.kp = kp
        m.kd = kd
        m.q = float(frame[local_idx])

    cmd.motor_cmd = motors
    return frame_idx


# ========== Callbacks ==========

def on_low_state(msg: br.LowState):
    """
    Low-level joint + IMU state callback.
    Prints compact diagnostic information to avoid excessive output.
    """
    imu = msg.imu_state
    rpy = imu.rpy
    motors = msg.motor_state_parallel

    # Print joint count and first few joint positions
    positions = [m.q for m in motors[:4]]

    print(f"[LowState] rpy(deg) = "
          f"{[round(v * 180.0 / math.pi, 1) for v in rpy]}, "
          f"first 4 q = {[round(v, 3) for v in positions]}")


def on_odom(msg: br.Odometer):
    """
    Odometry callback.
    """
    print(f"[Odom] x={msg.x:.3f}, y={msg.y:.3f}, theta={msg.theta:.3f}")


def on_hand_data(msg: br.HandReplyData):
    """
    Hand joint state callback.
    """
    hand_index = msg.hand_index
    hand_type = msg.hand_type
    params = msg.hand_data

    # Print angle/force for the first two fingers
    brief = [
        (p.seq, p.angle, p.force) for p in params[:2]
    ]
    print(f"[HandData] hand_index={hand_index}, type={hand_type}, "
          f"first params(seq, angle, force)={brief}")


def on_hand_touch(msg: br.HandTouchData):
    """
    Tactile array callback.
    """
    hand_index = msg.hand_index
    hand_type = msg.hand_type
    t = msg.touch_data

    # Lengths of tactile vectors for each finger
    lens = {
        "one": len(t.finger_one),
        "two": len(t.finger_two),
        "three": len(t.finger_three),
        "four": len(t.finger_four),
        "five": len(t.finger_five),
        "palm": len(t.finger_palm),
    }
    print(f"[HandTouch] hand_index={hand_index}, type={hand_type}, "
          f"lens={lens}")


# ========== Argument parsing ==========

def parse_args():
    parser = argparse.ArgumentParser(
        description="B1 low-level IO all-in-one example (pub/sub switches)"
    )
    parser.add_argument(
        "--domain-id", type=int, default=0,
        help="DDS domain id (default: 0)"
    )
    parser.add_argument(
        "--iface", type=str, default="",
        help="DDS network interface; empty string means default interface"
    )
    parser.add_argument(
        "--subs", type=str, default="all",
        help=(
            "Subscriptions, comma-separated: "
            "low_state,odom,hand_data,hand_touch,all,none (default: all)"
        ),
    )
    parser.add_argument(
        "--pubs", type=str, default="lowcmd",
        help="Publishers, comma-separated: lowcmd,all,none (default: lowcmd)"
    )
    return parser.parse_args()


def parse_switches(raw: str, valid: set, default_all: bool) -> set:
    """
    Parse a comma-separated switch string such as 'a,b,c', supporting 'all'/'none'.
    """
    s = raw.strip().lower()
    if s == "all":
        return set(valid)
    if s == "none" or not s:
        return set()

    result = set()
    for item in s.split(","):
        item = item.strip()
        if not item:
            continue
        if item not in valid:
            print(f"[Warn] unknown switch '{item}', ignored.")
            continue
        result.add(item)

    if not result and default_all:
        # Fallback: if all tokens are invalid and default_all=True, enable all
        return set(valid)
    return result


# ========== Main loop ==========

def main():
    args = parse_args()

    # --------- 1. Parse switches ---------
    valid_subs = {"low_state", "odom", "hand_data", "hand_touch"}
    enabled_subs = parse_switches(args.subs, valid_subs, default_all=True)

    valid_pubs = {"lowcmd"}
    enabled_pubs = parse_switches(args.pubs, valid_pubs, default_all=False)

    print("Subs enabled :", sorted(enabled_subs) if enabled_subs else "[]")
    print("Pubs enabled :", sorted(enabled_pubs) if enabled_pubs else "[]")

    if not enabled_subs and not enabled_pubs:
        print("[Info] No pub/sub enabled; the process will idle until Ctrl+C.")

    # --------- 2. Initialize DDS ---------
    init_dds(domain_id=args.domain_id, iface=args.iface)

    # --------- 3. Initialize pub/sub ---------
    low_state_sub = None
    odom_sub = None
    hand_data_sub = None
    hand_touch_sub = None
    lowcmd_pub = None

    # -- subscriptions --
    # if "low_state" in enabled_subs:
    #     low_state_sub = br.B1LowStateSubscriber(on_low_state)
    #     low_state_sub.InitChannel()
    #     print("LowState channel:", low_state_sub.GetChannelName())

    # if "odom" in enabled_subs:
    #     odom_sub = br.B1OdometerStateSubscriber(on_odom)
    #     odom_sub.InitChannel()
    #     print("Odometer channel:", odom_sub.GetChannelName())

    # if "hand_data" in enabled_subs:
    #     hand_data_sub = br.B1LowHandDataScriber(on_hand_data)
    #     hand_data_sub.InitChannel()
    #     print("HandData channel:", hand_data_sub.GetChannelName())

    # if "hand_touch" in enabled_subs:
    #     hand_touch_sub = br.B1LowHandTouchDataScriber(on_hand_touch)
    #     hand_touch_sub.InitChannel()
    #     print("HandTouch channel:", hand_touch_sub.GetChannelName())

    # -- publishers --
    if "lowcmd" in enabled_pubs:
        lowcmd_pub = br.B1LowCmdPublisher()
        lowcmd_pub.InitChannel()
        print("LowCmd pub channel:", lowcmd_pub.GetChannelName())

    # --------- 4. Main loop ---------
    # If publisher is enabled, run 3-second interpolation; otherwise only subscriptions are active.
    running = True

    def handle_sigint(sig, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, handle_sigint)

    traj = None
    frame_idx = 0
    dt = 0.02  # Loop period (seconds); must match trajectory generation

    if lowcmd_pub is not None:
        cmd = create_base_lowcmd()

        # Initialize joints 2–9 to the start posture to avoid a jump at the first frame
        motors = cmd.motor_cmd
        for local_idx, q0 in enumerate(START_ANGLES):
            j = 2+local_idx
            if j >= len(motors):
                break
            motors[j].q = q0
        cmd.motor_cmd = motors

        traj = generate_joints_down_trajectory(duration_sec=5.0, dt=dt)
        print("\nRunning with LowCmd publishing: joints 0–9 interpolate to 0 in 3 seconds. Press Ctrl+C to exit.\n")
    else:
        cmd = None
        print("\nRunning without LowCmd publishing (subscriptions only). Press Ctrl+C to exit.\n")

    try:
        while running:
            if lowcmd_pub is not None and cmd is not None and traj is not None:
                # Apply the current trajectory frame to joints 2–9
                apply_joint_trajectory(cmd, frame_idx, traj)

                # Increase frame index until the last frame is reached, then hold the final pose
                if frame_idx < len(traj) - 1:
                    frame_idx += 1 

                ok = lowcmd_pub.Write(cmd)
                if not ok:
                    # Typically false when there are no subscribers; informational only
                    print("[Warn] LowCmd Write() returned false")

            # Keep the loop running even without publishers so that subscription callbacks continue to be invoked
            time.sleep(dt)
    finally:
        print("\nCleaning up channels...")

        if low_state_sub is not None:
            low_state_sub.CloseChannel()
        if odom_sub is not None:
            odom_sub.CloseChannel()
        if hand_data_sub is not None:
            hand_data_sub.CloseChannel()
        if hand_touch_sub is not None:
            hand_touch_sub.CloseChannel()
        if lowcmd_pub is not None:
            lowcmd_pub.CloseChannel()

        print("Exited.")
        

if __name__ == "__main__":
    main()
